mapper.select:
SELECT msg_id, student_id, student_name, teacher_id, teacher_name, question_content, reply_content, is_featured, featured_title, created_at
FROM qa_message
WHERE msg_id = #{msgId}

mapper.update:
UPDATE qa_message
SET reply_content = #{replyContent}
WHERE msg_id = #{msgId}

UPDATE qa_message
SET is_featured = 1, featured_title = #{featuredTitle}
WHERE msg_id = #{msgId}
